  return (
    <div
      style={{
        background: 'hsl(140, 18%, 3%)',
        alignItems: 'center',
        display: 'flex',
        justifyContent: 'center',
        minHeight: '100vh',
        width: '100vw',
      }}
    >

      <div className="mystic-card theme-mars" style={{ width: 'fit-content', minWidth: '40rem', margin: '5rem' }}>
        <div className="card-letter" style={{ fontSize: '1.0rem', textAlign: 'center' }}>Reunited once, just to be seperated.</div>
        <div className="corner top left"></div>
        <div className="corner top right"></div>
        <div className="corner bottom left"></div>
        <div className="corner bottom right"></div>

        <div className="card-corner-letter top-left">🏳️‍🌈</div>
        <div className="card-corner-letter bottom-right">🏳️‍🌈</div>

        <pre
            style={{
              fontFamily: '"Courier New", Courier, monospace',
              lineHeight: '1.0',
              fontSize: '0.2rem',
              color: 'var(--mystic-border, #e0e7ff)',
              textShadow: '0 0 6px var(--mystic-border, rgba(224, 231, 255, 0.4))',
              margin: '1rem auto -1rem auto',
              userSelect: 'none',
              textAlign: 'center',
            }}
          >
            {asciiArt}
          </pre>

        

      </div>
    </div>
  );
